// Usage: node scripts/generate-og-image.js
// Output: public/og-image.png — what og:image / twitter:image point at
// (views/partials/_head.ejs, views/showcase/index.ejs).
//
// Rasterises brand/og-card.svg — which is itself generated by brand/build.mjs
// from brand/geometry.mjs. The card is never drawn here: this script only
// converts it, so run `node brand/build.mjs` first if the geometry changed.
//
// It used to draw its own "KUIejs" card with CSS and write it to
// public/assets/img/, which neither matched the brand mark nor sat at the
// /og-image.png URL the head tags advertise.

const puppeteer = require('puppeteer');
const path = require('path');
const fs   = require('fs');

const OUT_PATH  = path.resolve(__dirname, '../public/og-image.png');
const CARD_PATH = path.resolve(__dirname, '../brand/og-card.svg');
const WIDTH  = 1200;
const HEIGHT = 630;

function buildHtml() {
  // An <img> rather than an inline <svg> so nothing in the page's CSS can
  // reach into the artwork.
  const svg = fs.readFileSync(CARD_PATH, 'utf8');
  const uri = `data:image/svg+xml;base64,${Buffer.from(svg).toString('base64')}`;
  return `<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8">
<style>
  * { margin: 0; padding: 0; box-sizing: border-box; }
  body { width: ${WIDTH}px; height: ${HEIGHT}px; overflow: hidden; }
  img  { width: ${WIDTH}px; height: ${HEIGHT}px; display: block; }
</style>
</head>
<body><img src="${uri}" alt=""></body>
</html>`;
}

(async () => {
  const browser = await puppeteer.launch({
    headless: true,
    args: ['--no-sandbox', '--disable-setuid-sandbox', '--disable-dev-shm-usage'],
  });

  const page = await browser.newPage();
  await page.setViewport({ width: WIDTH, height: HEIGHT, deviceScaleFactor: 1 });
  await page.setContent(buildHtml(), { waitUntil: 'load' });
  fs.mkdirSync(path.dirname(OUT_PATH), { recursive: true });
  await page.screenshot({ path: OUT_PATH, type: 'png', clip: { x: 0, y: 0, width: WIDTH, height: HEIGHT } });
  await browser.close();

  console.log(`✓ og-image.png (${WIDTH}x${HEIGHT}) → ${OUT_PATH}`);
})();
